/// it's closed. Since this runs on the single actor loop, that blocked
/// tick/election/command processing for the node entirely, not just delayed
/// egress. Uses a tiny `outgoing_capacity` and never drains it, so it fills
/// up almost immediately (the node has configured peers and sends BLE
/// heartbeats regardless of whether anyone's listening).
///
/// Notify-path (`TaggedProposal` / `Assigned`) backpressure is covered by
/// [`notify_egress_does_not_stall_when_outgoing_full`].
#[tokio::test]
async fn full_outgoing_channel_does_not_stall_actor_loop() {
    let nodes: Vec<NodeId> = vec![1, 2, 3];
    let cfg = RuntimeConfig {
        tick_period: Duration::from_millis(2),
        egress_period: Duration::from_millis(1),
        outgoing_capacity: 2,
        ..Default::default()
    };
    let op = build_op(1, nodes);
    let h = spawn_actor::<TestEntry, MemoryStorage<TestEntry>, TokioRuntime>(op, cfg);

    // Let the outgoing channel fill up completely without ever draining it.
    tokio::time::sleep(Duration::from_millis(100)).await;

    // The actor loop must still be responsive to commands -- if
    // flush_outgoing blocked on a full channel, this would hang.
    let idx = timeout(Duration::from_millis(500), h.decided_idx())
        .await
        .expect("actor loop appears stalled with a full outgoing channel");
    assert_eq!(idx, 0);

    // Draining now should still deliver messages (not silently and
    // permanently lost) once the consumer catches up.
    let out = h.outgoing_messages();
    timeout(Duration::from_secs(2), out.recv())
        .await
        .expect("no message ever arrived once draining resumed")
        .expect("outgoing channel closed unexpectedly");
}

/// Like `spawn_cluster`, but each node's outgoing drain can be paused via the
/// returned per-pid flags. While a node's flag is `true`, its drain task stops
/// calling `recv`, so that node's bounded `outgoing_messages` channel fills
/// and further egress hits backpressure -- without tearing down the rest of

fn drain_notifiers(&mut self) {
    let decided = self.op.get_decided_idx();
    let now = Instant::now();
    let cur_ballot = self.op.get_promise();
    let old = std::mem::take(&mut self.pending);
    for p in old {
        match p.assigned {
            Some((idx, _)) if idx <= decided => {
                let _ = p.reply.send(Ok(idx));
            }
            Some((idx, ballot)) if ballot < cur_ballot => {
                let _ = p
                    .reply
                    .send(Err(AppendError::Superseded { log_entry_idx: idx }));
            }
            _ if now > p.deadline => {
                let _ = p.reply.send(Err(AppendError::Timeout));
            }
            _ => self.pending.push_back(p),
        }
    }
}

/// Append an entry and await its decided log index.
///
/// Works from any node: the actor tags the entry with a unique id, routes it to
/// the current leader, and resolves the future when the assigned log index is
/// decided. If no leader is known yet, the call waits rather than failing fast --
/// it resolves once a leader is elected, or with `Timeout` if none is elected in
/// time. Fails with:
/// - [`AppendError::Timeout`] if the entry is not decided within
///   [`RuntimeConfig::append_notify_timeout`] (including when no leader was ever
///   elected in that time);
/// - [`AppendError::Propose`] if the underlying propose call itself failed (e.g. a
///   reconfiguration is already pending) -- only when this node owns the pending
///   call, otherwise it still resolves via `Timeout`;
/// - [`AppendError::Superseded`] if a leader change occurred before decision --
///   a heuristic, not a certainty; see its doc comment for why, and check the
///   returned index yourself if you need to know for sure;
/// - [`AppendError::TooManyOutstanding`] if [`RuntimeConfig::max_pending_appends`]
///   outstanding calls are already queued.
///
/// Uses [`RuntimeConfig::append_notify_timeout`] as the deadline; use
/// [`Self::append_notify_with_timeout`] to override it for a single call.
pub async fn append_notify(&self, entry: T) -> Result<usize, AppendError<T>> {
    self.append_notify_inner(entry, None).await
}

pub fn spawn_actor<T, B, R>(op: OmniPaxos<T, B>, cfg: RuntimeConfig) -> OmniPaxosHandle<T>
where
    T: ActorEntry,
    B: Storage<T> + Send + 'static,
    R: AsyncRuntime,
{
    let (cmd_tx, cmd_rx) = async_channel::bounded(cfg.cmd_channel_capacity);
    let (outgoing_tx, outgoing_rx) = async_channel::bounded(cfg.outgoing_capacity);
    let (incoming_tx, incoming_rx) = async_channel::bounded(cfg.incoming_capacity);
    let (event_tx, events_rx) = async_channel::bounded(cfg.event_capacity);

    let state = ActorState::new(
        op,
        cmd_rx,
        incoming_rx,
        outgoing_tx,
        event_tx,
        ActorConfig::from(&cfg),
    );

    R::spawn(run::<T, B, R>(state, PhantomData::<fn() -> R>));

    OmniPaxosHandle {
        cmd_tx,
        events_rx,
        outgoing_rx,
        incoming_tx,
        decided_channel_capacity: cfg.decided_channel_capacity,
    }

pub(crate) fn resend_messages_leader(&mut self) {
    match self.state.1 {
        Phase::Prepare => {
            // Resend Prepare
            let preparable_peers = self.leader_state.get_preparable_peers(&self.peers);
            for peer in preparable_peers {
                self.send_prepare(peer);
            }
        }
        Phase::Accept => {
            // Resend AcceptStopSign or StopSign's decide
            if let Some(ss) = self.internal_storage.get_stopsign() {
                let decided_idx = self.internal_storage.get_decided_idx();
                for follower in self.leader_state.get_promised_followers() {
                    if self.internal_storage.stopsign_is_decided() {
                        self.send_decide(follower, decided_idx, true);
                    } else if self.leader_state.get_accepted_idx(follower)
                        != self.internal_storage.get_accepted_idx()
                    {
                        self.send_accept_stopsign(follower, ss.clone(), true);
                    }
                }
            }
            // Resend Prepare
            let preparable_peers = self.leader_state.get_preparable_peers(&self.peers);
            for peer in preparable_peers {
                self.send_prepare(peer);
            }
        }
        Phase::Recover => (),
        Phase::None => (),
    }
}

pub(crate) fn resend_messages_follower(&mut self) {
    match self.state.1 {
        Phase::Prepare => {
            // Resend Promise
            match &self.cached_promise_message {
                Some(promise) => {
                    self.outgoing.push(Message::SequencePaxos(PaxosMessage {
                        from: self.pid,
                        to: promise.n.pid,
                        msg: PaxosMsg::Promise(promise.clone()),
                    }));
                }
                None => {
                    // Shouldn't be possible to be in prepare phase without having
                    // cached the promise sent as a response to the prepare
                    #[cfg(feature = "logging")]
                    warn!(self.logger, "In Prepare phase without a cached promise!");
                    self.state = (Role::Follower, Phase::Recover);
                    self.send_preparereq_to_all_peers();
                }
            }
        }
        Phase::Recover => {
            // Resend PrepareReq
            self.send_preparereq_to_all_peers();
        }
        Phase::Accept => (),
        Phase::None => (),
    }
}

pub(crate) fn handle_accepted(&mut self, accepted: Accepted, from: NodeId) {
    #[cfg(feature = "logging")]
    trace!(
        self.logger,
        "Got Accepted from {}, idx: {}, chosen_idx: {}, accepted: {:?}",
        from,
        accepted.accepted_idx,
        self.internal_storage.get_decided_idx(),
        self.leader_state.accepted_indexes
    );
    if accepted.n == self.leader_state.n_leader && self.state == (Role::Leader, Phase::Accept) {
        self.leader_state
            .set_accepted_idx(from, accepted.accepted_idx);
        if accepted.accepted_idx > self.internal_storage.get_decided_idx()
            && self.leader_state.is_chosen(accepted.accepted_idx)
        {
            let decided_idx = accepted.accepted_idx;
            self.internal_storage
                .set_decided_idx(decided_idx)
                .expect(WRITE_ERROR_MSG);
            for pid in self.leader_state.get_promised_followers() {
                let latest_accdec = self.get_latest_accdec_message(pid);
                match latest_accdec {
                    Some(accdec) => accdec.decided_idx = decided_idx,
                    None => self.send_decide(pid, decided_idx, false),
                }
            }
        }
    }
}

fn reply_accepted(&mut self, n: Ballot, accepted_idx: usize) {
    let latest_accepted = self.get_latest_accepted_message(n);
    match latest_accepted {
        Some(acc) => acc.accepted_idx = accepted_idx,
        None => {
            let accepted = Accepted { n, accepted_idx };
            let cached_idx = self.outgoing.len();
            self.latest_accepted_meta = Some((n, cached_idx));
            self.outgoing.push(Message::SequencePaxos(PaxosMessage {
                from: self.pid,
                to: n.pid,
                msg: PaxosMsg::Accepted(accepted),
            }));
        }
    }
}

pub(crate) fn flush_batch_follower(&mut self) {
    let accepted_idx = self.internal_storage.get_accepted_idx();
    let new_accepted_idx = self.internal_storage.flush_batch().expect(WRITE_ERROR_MSG);
    if new_accepted_idx > accepted_idx {
        self.reply_accepted(self.get_promise(), new_accepted_idx);
    }
}

/// Detects if a Prepare, Promise, AcceptStopSign, Decide of a Stopsign, or PrepareReq message
/// has been sent but not been received. If so resends them. Note: We can't detect if a
/// StopSign's Decide message has been received so we always resend to be safe.
pub(crate) fn resend_message_timeout(&mut self) {
    match self.state.0 {
        Role::Leader => self.resend_messages_leader(),
        Role::Follower => self.resend_messages_follower(),
    }
}

/// Flushes any batched log entries and sends their corresponding Accept or Accepted messages.
pub(crate) fn flush_batch_timeout(&mut self) {
    match self.state {
        (Role::Leader, Phase::Accept) => self.flush_batch_leader(),
        (Role::Follower, Phase::Accept) => self.flush_batch_follower(),
        _ => (),
    }
}

